// Code generated by Claude (Anthropic), an AI system.
// Every rule the AI follows, in one file the team can edit. The owner's words: "an AI that will have rules".
// Each rule says where it comes from: the team's own texts (docs, tips, the screens) or the machine (src/config.js,
// src/nasa-rules.js, src/engine.js). Nothing here is new policy: a rule the program needs that the team has not
// written yet is marked confirm: 'TO CONFIRM' and says what is open.
// The rules work in three layers:
//   before  code that runs before the model: what the model may get, and the risk words that open Help now first;
//   prompt  sentences of the system prompt the model is given (systemPrompt());
//   after   code that checks every answer before anyone sees it (checkAnswer()); a held answer is replaced by a
//           fixed safe text that names the rule. Only the count is kept, never the text.
import { matchesRisk, plainText, RISK_RULE } from './support.js';

const MIND = 'docs/MIND_SUPPORT.md';
const ARCH = 'docs/ARCHITECTURE.md';

// ---------- reading past odd letters and spacing ----------
// A rule must not be dodged by how a word is written (found by the independent check: "You hаve hypertension" with
// a Cyrillic letter, "i b u p r o f e n", "ibu-pro-fen", an invisible character, full-width letters, a line break).
// Each text is read in several forms and a check that matches any form counts: compatibility letters made plain
// (full-width, bold maths letters, ligatures), invisible characters dropped, line breaks read as spaces, a word
// spelled letter by letter joined, Cyrillic and Greek letters that look like Latin ones read as Latin, a word cut by
// hyphens or dots joined, digits used as letters ("su1cide", "4OO mg") read back, and short forms written out.
const INVISIBLE = /[­͏؜ᅟᅠ឴឵᠋-᠏​-‏‪-‮⁠-⁯ㅤ︀-️﻿ﾠ]/g;
const swap = (from, to) => { const m = new Map([...from].map((c, i) => [c, to[i]])); return (t) => [...t].map((c) => m.get(c) || c).join(''); };
const UPPER_LOOKALIKE = swap('АВЕКМНОРСТУХІЈЅΑΒΕΗΙΚΜΝΟΡΤΥΧΖ', 'ABEKMHOPCTYXIJSABEHIKMNOPTYXZ');
const LOWER_LOOKALIKE = swap('авеёкмнорстухіїјѕԁԛԝһӏɡαβεηικνορτυχγ', 'abeekmhopctyxiijsdqwhlgabenikvoptuxy');
// Letters of another script than Latin (the micro sign of "µm" counts as Latin).
const FOREIGN = /(?=\p{L})[^\p{Script=Latin}µμ]/u;
const clean = (text) => String(text ?? '').normalize('NFKC').replace(INVISIBLE, '');
const base = (text) => plainText(clean(text));
// "i b u p r o f e n", "d.o.c.t.o.r": three or more single letters in a row become one word. The second way leaves a
// leading "a" or "i" as its own word ("i am a d o c t o r").
const SPELLED = /(?<!\p{L})(?:\p{L}[ ._*·/|-]+){2,}\p{L}(?!\p{L})/gu;
const SPELLED_AFTER_WORD = /(?<!\p{L})(?![ai][ ._*·/|-])(?:\p{L}[ ._*·/|-]+){2,}\p{L}(?!\p{L})/gu;
const joinSpelled = (t, afterWord = false) => t.replace(afterWord ? SPELLED_AFTER_WORD : SPELLED, (m) => m.replace(/[^\p{L}]/gu, ''));
// Digits used as letters: "4oo mg" is 400 mg, "su1cide" is suicide (only in words that hold two letters in a row).
const leet = (t) => t.replace(/\b\d[\do]+\b/g, (m) => m.replace(/o/g, '0'))
  .replace(/[a-z0-9@$]*[a-z][a-z0-9@$]*/g, (w) => (/[0-9@$]/.test(w) && /[a-z]{2}/.test(w) ? w.replace(/0/g, 'o').replace(/1/g, 'i').replace(/3/g, 'e').replace(/4|@/g, 'a').replace(/5|\$/g, 's').replace(/7/g, 't') : w));
const SHORT_FORMS = [[/\b(it|that|this|there|what|he|she|which)'s\b/g, '$1 is'], [/\byou're\b/g, 'you are'], [/\bi'm\b/g, 'i am'], [/\byou've\b/g, 'you have'], [/\bthey're\b/g, 'they are'], [/\bwe're\b/g, 'we are']];
// The forms of a text the checks read. The first is the plain text itself.
export function readForms(text) {
  const raw = clean(text);
  // An invisible character between two words stands for a space; inside a word it stands for nothing.
  const spaced = String(text ?? '').normalize('NFKC').replace(INVISIBLE, ' ');
  const out = [plainText(raw), plainText(spaced)];
  for (const r of [raw, spaced]) {
    // Capital look-alikes first (a Greek capital eta reads as H, its small letter as n), then small ones.
    const mapped = LOWER_LOOKALIKE(plainText(UPPER_LOOKALIKE(r)));
    for (const latin of [joinSpelled(mapped), joinSpelled(mapped, true)]) {
      const joined = latin.replace(/(?<=[a-z])[-._*·](?=[a-z])/g, '');
      out.push(latin, joined, leet(joined), SHORT_FORMS.reduce((t, [re, to]) => t.replace(re, to), joined));
    }
  }
  return [...new Set(out.filter(Boolean))];
}
// True when a text has letters of another script than Latin, which the word list and the answer check cannot read.
export const notEnglish = (text) => FOREIGN.test(base(text));

// The draft risk words in Russian and Ukrainian, for the AI's input only: a translation of the draft list in
// src/support.js (RISK_PATTERNS), so a hard moment written in the crew's other languages also opens Help now first
// and never reaches the model. Stems, matched in lower case with "ё" read as "е". TO CONFIRM with the word list.
export const RISK_DRAFT_RU_UK = Object.freeze([
  /суицид|самоубий|суїцид|самогубств|самогубц/u,
  /(?:убить|убью|убиваю|повесить|повешу|порезать|порежу|резать|режу|навредить|наврежу|покалечить|вбити|вб'ю|вбиваю|повісити|повішу|порізати|поріжу|різати|ріжу|нашкодити|нашкоджу|скалічити)\s+(?:себя|себе|собі)/u,
  /повеситься|повешусь|повіситися|повішуся/u,
  /поконч(?:ить|у)\s+с\s+(?:собой|жизнью|всем)|покінч(?:ити|у)\s+(?:з|із)\s+(?:собою|життям|усім)/u,
  /свести\s+сч[её]ты\s+с\s+жизнью|звести\s+рахунки\s+(?:з|із)\s+життям/u,
  /самоповрежд|самоушкодж|селфхарм/u,
  /(?:хочу|хочется|хотел[аи]?\s+бы|готов[аы]?|собираюсь|хочеться|хотів\s+би|хотіла\s+б|готовий|готова|збираюся)\s+(?:умереть|сдохнуть|помереть|исчезнуть|уйти\s+из\s+жизни|померти|здохнути|зникнути|піти\s+з\s+життя)/u,
  /лучше\s+бы\s+я\s+(?:умер|умерла|сдох|не\s+родил)|краще\s+б\s+я\s+(?:помер|померла|здох|не\s+народ)/u,
  /лучше\s+без\s+меня|краще\s+без\s+мене/u,
  /не\s+(?:хочу|хочется|хочеться)\s+(?:больше\s+|більше\s+)?(?:жить|просыпаться|существовать|жити|прокидатися|існувати)/u,
  /(?:жить|жити)\s+не\s+хочу/u,
  /(?:нет|никакого|немає|нема|ніякого)\s+(?:смысла|причин[ыа]?|сенсу|причин[иі]?)\s+(?:жить|продолжать|жити|продовжувати)|незачем\s+жить|нема\s+для\s+чого\s+жити/u,
  /больше\s+не\s+могу|не\s+могу\s+(?:так\s+)?больше|більше\s+не\s+можу|не\s+можу\s+(?:так\s+)?більше/u,
  /никогда\s+не\s+проснуться|ніколи\s+не\s+прокинутис[яь]/u,
  /передоз/u,
]);
const riskRuUk = (text) => { const t = base(text).replace(/ё/g, 'е'); return [t, joinSpelled(t)].some((x) => RISK_DRAFT_RU_UK.some((re) => re.test(x))); };

