export const ruleById = (id) => AI_RULES.find((r) => r.id === id) || null;
const forKind = (kind) => (r) => !r.where || r.where.includes(kind);
// The short list both panels show: "Rules this AI follows".
export const visibleRules = (kind = 'analyse') => AI_RULES.filter((r) => r.show && forKind(kind)(r));
export const toConfirm = () => AI_RULES.filter((r) => r.confirm);

// ---------- layer 1: before the model ----------
// Risk words open Help now first; the model is never the first answer to them (and never sees that message).
// A message the checks cannot read (another script) does not go to the model either.
export function beforeModel(text) {
  if (readForms(text).some((t) => matchesRisk(t)) || riskRuUk(text)) return { ok: false, rule: 'risk-words-first', note: RISK_RULE.text };
  if (notEnglish(text)) return { ok: false, rule: 'english-only' };
  return { ok: true };
}
// What the model may get from a panel: only the lines the panel shows, as plain text, short. The private logs are
// left out by the screen already (summaryFor() without full); this cuts again by size, so nothing large slips in.
export const MAX_CONTEXT_CHARS = 2400;
export function shareable(lines) {
  const text = (Array.isArray(lines) ? lines : [lines]).filter((x) => typeof x === 'string' && x.trim()).join('\n');
  return text.length > MAX_CONTEXT_CHARS ? `${text.slice(0, MAX_CONTEXT_CHARS)}\n(more lines left out)` : text;
}

// ---------- layer 2: the system prompt ----------
const LEVEL_NAMES = { normal: 'normal', attention: 'attention', action: 'needs action', urgent: 'urgent' };
// kind: 'analyse' (an explanation of the readings in the panel) or 'session' (the anonymous talk).
// ctx: { level: 'normal' | 'attention' | 'action' | 'urgent' | null, red: boolean, data: string }
export function systemPrompt(kind, ctx = {}) {
  // The red rule goes in only when a reading is red, so the model does not send the person to steps that are not there.
  const rules = AI_RULES.filter((r) => r.prompt && forKind(kind)(r) && (r.id !== 'red-to-steps' || ctx.red));
  const lines = [
    kind === 'session'
      ? 'You are "AI support", a private talk program on the crew health computer of a space mission. You talk with a crew member: speak to them as "you". Listen, help them think, and keep them close to people.'
      : 'You are the AI of the crew health computer of a space mission. You talk with a crew member: speak to them as "you". Explain their own readings below in plain words: what each reading is, and what the automation says about it.',
    'Rules you always follow:',
    ...rules.map((r, i) => `${i + 1}. ${r.prompt}`),
  ];
  if (kind === 'analyse') {
    lines.push('', `Level set by the automation: "${LEVEL_NAMES[ctx.level] || 'not given'}" (the levels from low to high: normal, attention, needs action, urgent; a level is a status, not the person's focus).${ctx.red ? ' At least one reading is past a red limit.' : ''}`);
    lines.push('The readings the automation flagged, with the program\'s norms and sources (one per line):', ctx.data || '(nothing)');
  }
  return lines.join('\n');
}

// ---------- layer 3: the check of every answer ----------
// The answer is made plain (lower case, one kind of apostrophe), then each check runs. A match right after a
// negation ("not", "never", "don't") does not count, so "I am not a doctor" and "do not ignore the alarm" pass.
const CONDITIONS = [
  'disease', 'disorder', 'syndrome', 'infection', 'condition', 'deficiency', 'failure', 'heart attack', 'stroke', 'cancer', 'tumou?r',
  'hypertension', 'hypotension', 'tachycardia', 'bradycardia', 'arrhythmia', 'atrial fibrillation', 'fibrillation', 'hypoxia',
  'hypoxaemia', 'hypoxemia', 'anaemia', 'anemia', 'diabetes', 'hypoglyca?emia', 'hyperglyca?emia', 'fever', 'pneumonia', 'covid',
  'influenza', 'flu', 'depression', 'anxiety', 'ptsd', 'insomnia', 'sleep apnoea', 'sleep apnea', 'apnoea', 'apnea', 'dehydration',
  'concussion', 'burnout', 'bipolar', 'hypothermia', 'hyperthermia', 'sepsis', 'panic attack',
  // Vague names count too: "respiratory issues", "a heart problem".
  '(?:respiratory|heart|cardiac|lung|breathing|kidney|liver|thyroid|blood sugar|circulation|circulatory|neurological|mental health) (?:issues?|problems?|troubles?|disorders?)',
  // Word endings of illnesses, without the words that only share the ending.
  '[a-z]+itis', '(?!diagnosis\\b|prognosis\\b)[a-z]+osis', '(?!empathy\\b|sympathy\\b)[a-z]+pathy',
].join('|');
const ADJ = '(?:an? |some |early |mild |severe |acute |chronic |possible |clinical |serious )*';
const DRUGS = [
  'ibuprofen', 'paracetamol', 'acetaminophen', 'tylenol', 'advil', 'aspirin', 'naproxen', 'melatonin', 'zolpidem', 'ambien',
  'zaleplon', 'eszopiclone', 'modafinil', 'armodafinil', 'promethazine', 'scopolamine', 'meclizine', 'dimenhydrinate',
  'diphenhydramine', 'benadryl', 'loratadine', 'cetirizine', 'pseudoephedrine', 'amoxicillin', 'azithromycin', 'ciprofloxacin',
  'sertraline', 'fluoxetine', 'citalopram', 'escitalopram', 'paroxetine', 'bupropion', 'venlafaxine', 'mirtazapine', 'trazodone',
  'quetiapine', 'lithium', 'diazepam', 'lorazepam', 'alprazolam', 'clonazepam', 'xanax', 'valium', 'morphine', 'oxycodone',
  'codeine', 'tramadol', 'fentanyl', 'insulin', 'metformin', 'metoprolol', 'atenolol', 'propranolol', 'lisinopril', 'amlodipine',
  'nitroglycerin', 'epinephrine', 'atropine', 'naloxone', 'prednisone', 'dexamethasone', 'omeprazole', 'ondansetron', 'loperamide',
  'ssris?', 'benzodiazepines?', 'opioids?', 'beta[- ]blockers?', 'antihistamines?', 'antibiotics?', 'antidepressants?', 'sedatives?',
  'sleeping pills?', 'sleeping tablets?', 'sleep aids?', 'painkillers?', 'nsaids?', 'caffeine pills?',
].join('|');
const PROS = 'human|person|man|woman|doctor|physician|psychologist|psychiatrist|therapist|counsell?or|nurse|flight surgeon|medic|medical officer|clinician';

export const ANSWER_CHECKS = Object.freeze([
  // Says what it is: no claim to be a person or a professional, and no claim not to be an AI.
  { rule: 'says-what-it-is', re: new RegExp(`\\bi(?:'m| am) (?:a |an |your |the )?(?:real |actual |licensed |qualified )?(?:${PROS})\\b`) },
  { rule: 'says-what-it-is', re: new RegExp(`\\bas (?:a|an|your) (?:${PROS}),? i\\b`) },
  { rule: 'says-what-it-is', re: /\bi(?:'m| am) not (?:an? )?(?:ai|a\.i\.|program|computer program|bot|chatbot|machine|computer|language model|robot)\b/ },
  { rule: 'says-what-it-is', re: new RegExp(`\\byou(?:'re| are) (?:talking|speaking|chatting) (?:to|with) (?:a |an )?(?:real |actual )?(?:${PROS})\\b`) },
  { rule: 'says-what-it-is', re: new RegExp(`\\bi(?:'m| am) (?:dr\\.?|doctor) [a-z]|\\bspeaking as (?:a |an |your )?(?:real |actual |licensed |qualified )?(?:${PROS})\\b`) },
  // No diagnosis.
  { rule: 'no-diagnosis', re: new RegExp(`\\byou (?:have|'ve got|have got|are suffering from|suffer from|are having|may have|might have|could have|probably have|likely have|seem to have|appear to have|are showing signs of|show signs of) ${ADJ}(?:[a-z-]+ ){0,2}(?:${CONDITIONS})\\b`) },
  { rule: 'no-diagnosis', re: /\byou(?:'re| are) (?:clinically |probably |likely )?(?:depressed|hypertensive|hypotensive|diabetic|anaemic|anemic|hypoxic|bipolar|febrile|tachycardic|bradycardic|burnt out|burned out)\b/ },
  { rule: 'no-diagnosis', re: new RegExp(`\\b(?:this|that|it|these|your readings?|the readings?|your (?:heart rate|blood pressure|pulse|temperature|oxygen|glucose|sugar|sleep|mood)) (?:is|are|looks? like|sounds? like|suggests?|indicates?|points? to|means?|could be|might be|may be|is likely|are likely|is probably|are signs? of|is a sign of|is a symptom of|are symptoms of) ${ADJ}(?:signs? of |symptoms? of |case of )?(?:[a-z-]+ ){0,2}(?:${CONDITIONS})\\b`) },
  { rule: 'no-diagnosis', re: /\b(?:my|the|a|your|this) diagnosis (?:is|would be|here is)\b|\bdiagnosis:|\bi (?:would |can |will )?diagnose\b|\byou (?:are|were|could be|would be) diagnosed\b/ },
  // "..., which may indicate hypoxia", "a sign of dehydration": an illness named next to the person's readings.
  { rule: 'no-diagnosis', re: new RegExp(`\\b(?:which|that) (?:may |might |could |can |would )?(?:indicates?|suggests?|means?|points? to|be a sign of|is a sign of) ${ADJ}(?:[a-z-]+ ){0,2}(?:${CONDITIONS})\\b`) },
  { rule: 'no-diagnosis', re: new RegExp(`\\b(?:signs?|symptoms?|indication) of ${ADJ}(?:[a-z-]+ )?(?:${CONDITIONS})\\b`) },
  // No medicines or doses.
  // A medicine's name or a dose counts also after "not": "do not take ibuprofen" is medicine advice too.
  { rule: 'no-medicine', strict: true, re: new RegExp(`\\b(?:${DRUGS})\\b`) },
  // A unit of a reading is not a dose: "95 mg/dL" and "milligrams per decilitre" are the glucose reading's own unit.
  { rule: 'no-medicine', strict: true, re: /\b\d+(?:[.,]\d+)? ?(?:(?:mg|mcg|µg|μg|ug|milligrams?|micrograms?)(?! ?(?:\/|per ) ?(?:dl|decilit(?:er|re)s?|l|lit(?:er|re)s?|kg|kilograms?)\b)|iu|units? of|tablets?|pills?|capsules?|puffs?|drops?|doses?)\b/ },
  { rule: 'no-medicine', strict: true, re: /\b(?:one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty|fifty|hundred|thousand|half a|a quarter of a) (?:[a-z]+ )?(?:mg|milligrams?|micrograms?|tablets?|pills?|capsules?)\b(?! ?(?:\/|per ) ?(?:dl|decilit))|\b(?:milligrams?|micrograms?) of\b/ },
  { rule: 'no-medicine', re: /\b(?:take|taking|try|use|have|swallow|pop|start) (?:a |an |one |two |some |your |a few |the )?(?:pills?|tablets?|capsules?|medicines?|medications?|meds|supplements?|dose)\b/ },
  { rule: 'no-medicine', re: /\b(?:dosage|dose of|double the dose|increase the dose)\b/ },
  // The automation decides: never ignore, silence or skip, never call the alarm or the level wrong.
  { rule: 'automation-decides', re: /\b(?:ignore|disregard|dismiss|silence|mute|turn off|switch off|disable|skip|bypass|override|cancel|stop following)(?: the| this| that| these| those| your| any| all)? (?:alarms?|alerts?|warnings?|alarm sounds?|red limits?|limits?|levels?|steps?|numbered steps|what to do|procedures?|checklists?)\b/ },
  { rule: 'automation-decides', re: /\b(?:no need to|you don't need to|you do not need to|there is no need to|don't bother to|do not bother to|not necessary to|you can skip|you can ignore|it is safe to ignore|it's safe to ignore)(?: \w+){0,2}? ?(?:follow|message|call|tell|contact|act|respond|press|do the steps|check)\b/ },
  { rule: 'automation-decides', re: /\bfalse alarm\b|\b(?:the |this )?alarm (?:is|was) (?:probably |likely |just |only )?(?:wrong|false|a mistake|an error|a glitch|nothing|fine|ok|okay|harmless|not real|not important)\b|\bthe (?:level|levels|automation|machine|program|red limit) (?:is|are) (?:probably |likely )?(?:wrong|mistaken|overreacting|too strict)\b/ },
  // Said the other way round: "the alarm can be ignored", "the steps are optional".
  { rule: 'automation-decides', re: /\b(?:alarms?|alerts?|warnings?|alarm sounds?|red limits?|limits?|levels?|steps?|numbered steps|procedures?|checklists?) (?:can|could|may|might|should) (?:safely |just |simply |all )?be (?:ignored|skipped|silenced|muted|dismissed|disregarded|bypassed|overridden|turned off|switched off|left out)\b|\b(?:the |these |those )?(?:numbered )?steps (?:are|is) (?:optional|not needed|unnecessary|not necessary|not important)\b/ },
  // Against the level: reassurance when the automation says needs action or urgent, or about a reading the person
  // typed that the automation has not checked (selfReported: "my heart rate is 180").
  { rule: 'automation-decides', when: (ctx) => ctx.red || ctx.level === 'action' || ctx.level === 'urgent' || ctx.selfReported,
    re: /\b(?:nothing to worry about|no need to worry|no cause for (?:concern|alarm|worry)|nothing serious|not serious|not urgent|not (?:a |any )?(?:concern|problem|emergency)|not dangerous|you(?:'re| are) (?:fine|ok|okay|healthy|safe|alright|all right)|(?:everything|all) (?:is |looks |seems )?(?:fine|ok|okay|normal|good|well)|(?:all|these|your) readings (?:are|look|seem) (?:fine|ok|okay|normal|good|healthy)|perfectly (?:normal|healthy|fine)|no action (?:is )?(?:needed|required)|it can wait|don't worry|do not worry|no worries|there(?:'s| is) no (?:problem|issue|danger|concern|risk)|ignore (?:it|them))\b/ },
  // The person's own flagged reading called normal while the automation says needs action or urgent.
  { rule: 'automation-decides', when: (ctx) => ctx.red || ctx.level === 'action' || ctx.level === 'urgent' || ctx.selfReported,
    re: /\b(?:your|this|that) (?:reading|readings|value|values|heart rate|pulse|blood pressure|oxygen|oxygen level|spo2|temperature|glucose|blood sugar|sugar|breathing rate|level)(?: of [0-9.,%/ a-z]{1,24}?)? (?:is|are|looks?|seems?) (?:still |perfectly |completely |quite |totally )?(?:normal|fine|healthy|okay|ok|safe|(?:within|in) (?:the |a )?(?:normal|healthy|safe|expected) (?:range|limits?))\b/ },
  // Against a red or urgent level, or a reading the automation has not checked: making the doctor depend on later
  // ("if it persists", "if your heart rate remains high", "monitor it over time"); the automation already called.
  { rule: 'automation-decides', when: (ctx) => ctx.red || ctx.level === 'urgent' || ctx.selfReported,
    re: /\b(?:if|when|should) (?:it|this|that|they|the reading|the readings|the value|symptoms?|your symptoms|your [a-z0-9 ]{1,24}?) (?:persists?|continues?|remains?|stays?|keeps? (?:going|rising|falling)|gets? worse|worsens?|does not improve|doesn't improve|do not improve|don't improve)\b|\bif (?:it|this|that|the reading|the value|your [a-z0-9 ]{1,24}) (?:falls|drops|goes|gets|rises|climbs|moves) (?:further )?(?:below|under|above|over|lower|higher)\b|\bwait and see\b|\bkeep an eye on it\b|\b(?:monitor|watch) (?:it|this|this reading|the reading|your [a-z0-9 ]{1,24}?) (?:closely |carefully )?(?:over time|for now|for a while|and see)\b/ },
  // A finding the automation did not make: "the automation has flagged your heart rate" when no heart rate is in the
  // lines the panel gave the AI (seen on this laptop after "my heart rate is 180").
  { rule: 'automation-decides', test: (t, ctx) => typeof ctx.data === 'string' && [...t.matchAll(/\b(?:the automation|the program|the machine|it) (?:has |have |had )?(?:flagged|recorded|measured|detected|registered|checked|found|logged) (?:your |a |the )?(heart rate|pulse|blood pressure|oxygen|spo2|blood oxygen|temperature|glucose|blood sugar|breathing rate|breathing|respiratory rate|sleep|weight|body mass|vo2max|aerobic capacity)\b/g)].some((m) => !MEASURE_WORDS[m[1]].some((w) => ctx.data.toLowerCase().includes(w))) },
  // Seen on this laptop: after a held answer the model copied the program's fixed text, with a rule it made up and
  // "The level is past a red limit" while nothing was red. The model never speaks as the rule check, and never
  // names a level or a red limit the automation did not set.
  { rule: 'says-what-it-is', re: /\bheld back by the rule\b|\bthis answer was held back\b|\bthis line is fixed, not ai\b/ },
  { rule: 'automation-decides', when: (ctx) => !ctx.red,
    re: /\b(?:level|levels|reading|readings|value|values|it|this|that|oxygen|heart rate|pulse|blood pressure|temperature|glucose|sugar) (?:is|are|was|were|has gone|have gone|went) (?:now |already )?(?:past|above|beyond|over|outside) (?:a|the|its|their) (?:red|urgent) limits?\b/ },
  { rule: 'automation-decides', test: (t, ctx) => Boolean(ctx.level) && [...t.matchAll(/\blevel(?: set by the automation| from the automation)? (?:is|was|has been set to|stays|remains|is now) "?(normal|attention|needs action|urgent)\b/g)].some((m) => m[1] !== LEVEL_NAMES[ctx.level]) },
  // Against the level: alarm words when the automation says normal.
  { rule: 'automation-decides', when: (ctx) => ctx.level === 'normal' && !ctx.red,
    re: /\b(?:emergency|life[- ]threatening|ambulance|hospital|emergency room|seek (?:immediate|urgent|emergency) (?:medical )?(?:help|care|attention)|this is urgent|it is urgent|it's urgent|dangerous)\b/ },
]);

// A match right after a negation does not count: "not", "never", "no", "n't", "do not", "don't".
const NEGATED = /(?:\bnot|\bnever|\bno|n't|\bdo not|\bdon't|\bwithout|\bnor)\s+(?:\w+\s+){0,1}$/;
function hits(re, text, strict = false) {
  const g = new RegExp(re.source, re.flags.includes('g') ? re.flags : `${re.flags}g`);
  for (const m of text.matchAll(g)) {
    const before = text.slice(Math.max(0, m.index - 24), m.index);
    if (strict || !NEGATED.test(before)) return true;
  }
  return false;
}

// The fixed safe texts. They name the rule; place is 'analyse' or 'session' (the doctor's button differs).
export function safeText(ruleId, place = 'analyse') {
  const r = ruleById(ruleId);
  const doctor = place === 'session' ? '"Tell the doctor on Earth"' : '"Message the doctor"';
  const why = {
    'says-what-it-is': 'This is an AI program, not a person, not a psychologist and not a doctor.',
    'no-diagnosis': `Only a doctor can say what this is. Use ${doctor} to ask your flight surgeon.`,
    'no-medicine': 'Ask your flight surgeon or the crew medical officer about any medicine or dose.',
    'automation-decides': `The levels, red limits and numbered steps come from the automation and stand as shown. Follow "What to do" and use ${doctor}.`,
    'english-only': 'The AI answers in English only, the language its rules are checked in. Please talk to a crewmate or your flight surgeon.',
  }[ruleId] || 'Please talk to a crewmate or your flight surgeon.';
  return `This answer was held back by the rule "${r ? r.title : ruleId}". ${why}`;
}
// A message that did not go to the model because the checks cannot read it.
export function notSentText(place = 'analyse') {
  return `This message did not go to the AI, by the rule "English only": the word list that opens Help now and the check of every answer read English only. Nothing was sent. Write in English, or talk to a crewmate${place === 'session' ? ' or press Help now' : ' or your flight surgeon'}.`;
}

// Check one answer. ctx: { level, red }. Returns { ok: true } or { ok: false, rule }.
export function checkAnswer(text, ctx = {}) {
  const forms = readForms(text);
  if (!forms.length) return { ok: true };
  // An answer the checks cannot read (another script, or look-alike letters inside words) is held as a whole.
  if (notEnglish(text)) return { ok: false, rule: 'english-only' };
  for (const c of ANSWER_CHECKS) {
    if (c.when && !c.when(ctx)) continue;
    if (forms.some((t) => (c.test ? c.test(t, ctx) : hits(c.re, t, c.strict)))) return { ok: false, rule: c.rule };
  }
  return { ok: true };
}

// Counts of held answers by rule, on this computer only: a number, never the text.
const HELD_KEY = 'jff-ai-held-v1';
const heldNow = {};
export function countHeld(ruleId, storage = globalThis.localStorage) {
  heldNow[ruleId] = (heldNow[ruleId] || 0) + 1;
  try {
    if (storage) {
      const all = JSON.parse(storage.getItem(HELD_KEY) || '{}');
      all[ruleId] = (Number(all[ruleId]) || 0) + 1;
      storage.setItem(HELD_KEY, JSON.stringify(all));
    }
  } catch { /* storage blocked: the count stays for this page only */ }
  return heldNow[ruleId];
}
export function heldCounts(storage = globalThis.localStorage) {
  try { if (storage) return { ...heldNow, ...JSON.parse(storage.getItem(HELD_KEY) || '{}') }; } catch { /* blocked */ }
  return { ...heldNow };
}
